CREATE TABLE public.foods (id text PRIMARY KEY, nombre text NOT NULL, categoria text NOT NULL, nutriente_clave text NOT NULL DEFAULT '', por_que text NOT NULL DEFAULT '', como_comerlo text NOT NULL DEFAULT '', image_url text, image_credit text, tags_restriccion text[] NOT NULL DEFAULT '{}');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.foods TO authenticated;
GRANT ALL ON public.foods TO service_role;
ALTER TABLE public.foods ENABLE ROW LEVEL SECURITY;
CREATE POLICY foods_read ON public.foods FOR SELECT TO authenticated USING (true);
CREATE POLICY foods_admin ON public.foods FOR ALL TO authenticated USING (public.es_admin()) WITH CHECK (public.es_admin());
CREATE TABLE public.variable_food_rules (id text PRIMARY KEY, analitos text[] NOT NULL DEFAULT '{}', categorias text[] NOT NULL DEFAULT '{}', estados text[] NOT NULL DEFAULT '{}', recomendados text[] NOT NULL DEFAULT '{}', limitar text[] NOT NULL DEFAULT '{}', mensaje text NOT NULL DEFAULT '', consejo text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.variable_food_rules TO authenticated;
GRANT ALL ON public.variable_food_rules TO service_role;
ALTER TABLE public.variable_food_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY food_rules_read ON public.variable_food_rules FOR SELECT TO authenticated USING (true);
CREATE POLICY food_rules_admin ON public.variable_food_rules FOR ALL TO authenticated USING (public.es_admin()) WITH CHECK (public.es_admin());
CREATE TABLE public.places (id text PRIMARY KEY, nombre text NOT NULL, tipo text NOT NULL, ciudad text NOT NULL, que_se_consigue text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE, DELETE ON public.places TO authenticated;
GRANT ALL ON public.places TO service_role;
ALTER TABLE public.places ENABLE ROW LEVEL SECURITY;
CREATE POLICY places_read ON public.places FOR SELECT TO authenticated USING (true);
CREATE POLICY places_admin ON public.places FOR ALL TO authenticated USING (public.es_admin()) WITH CHECK (public.es_admin());
CREATE POLICY foods_images_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'foods');
CREATE POLICY foods_images_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'foods' AND public.es_admin());
CREATE POLICY foods_images_admin_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'foods' AND public.es_admin()) WITH CHECK (bucket_id = 'foods' AND public.es_admin());
CREATE POLICY foods_images_admin_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'foods' AND public.es_admin());